def reject_injected_java_options():
    names = [name for name in ('JAVA_TOOL_OPTIONS', 'JDK_JAVA_OPTIONS', '_JAVA_OPTIONS') if name in os.environ]
    assert not names, 'Unexpected injected Java options: ' + ', '.join(names)


def write_new(path, value):
    with Path(path).open('x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write('\n')


def source_hashes():
    files = [HERE / name for name in ('run_diagnostic.py', 'analyze_pages.py', 'build_overlay_source.py', 'protocol.md')]
    files += sorted((HERE / 'helper-src').rglob('*.java'))
    for variant in VARIANTS:
        folder = GENERATED / variant
        files += sorted((folder / 'src').rglob('*.java')) + sorted((folder / 'preimage').rglob('*.java'))
        files += [folder / 'diagnostic-overlay.patch', folder / 'source-generation.json']
    return {str(path.relative_to(HERE)): identity.sha(path) for path in files}


def verify_descriptor(path):
    path = Path(path).resolve(strict=True)
    descriptor = json.loads(path.read_text())
    input_files = {}
    for key, hash_key in (
        ('classpathFile', 'classpathFileSha256'), ('classpathManifestFile', 'classpathManifestSha256'),
        ('sourceManifestFile', 'sourceManifestSha256'), ('provenanceFile', 'provenanceSha256'),
        ('sourceProvenanceFile', 'sourceProvenanceSha256'), ('productionPatchFile', 'productionPatchSha256'),
    ):
        if key in descriptor:
            assert identity.sha(descriptor[key]) == descriptor[hash_key], key
            input_files[descriptor[key]] = descriptor[hash_key]
    cp = Path(descriptor['classpathFile']).read_text().strip()
    manifest = identity.classpath_manifest(cp)
    assert manifest == json.loads(Path(descriptor['classpathManifestFile']).read_text())
    return {'path': str(path), 'sha256': identity.sha(path), 'descriptor': descriptor,
            'inputFiles': input_files, 'classpath': cp, 'manifest': manifest}


def prepare(args):
    reject_injected_java_options()
    common = verify_descriptor(args.original_runtime)
    candidate = verify_descriptor(args.candidate_runtime)
    original_cp, original_manifest = identity.original_identity()
    assert len(common['manifest']) == 128 and common['manifest'][1:] == original_manifest
    assert not common['descriptor'].get('diagnosticOnly', False)
    assert common['descriptor']['sharedOracleAndLaunchersUnchanged']
    assert len(candidate['manifest']) == 127
    assert all(candidate['manifest'][i] == original_manifest[i] for i in range(127) if i != 1)
    provenance = json.loads(Path(candidate['descriptor']['provenanceFile']).read_text())
    assert provenance['name'] == 'compact-page' and provenance['currentSourcesEqualEverySuccessfulValidation']
    assert provenance['sourceRoleDeltaVersusMeasured']['production'] == {
        'added': [], 'removed': [], 'changed': [str(PRODUCTION_REL)]}
    selected_sources = {
        'original': json.loads(identity.ORIGINAL_SOURCES.read_text()),
        'compact': json.loads(Path(candidate['descriptor']['sourceManifestFile']).read_text()),
    }
    sources = source_hashes()
    runtimes = {}
    for variant in VARIANTS:
        folder = GENERATED / variant
        generation = json.loads((folder / 'source-generation.json').read_text())
        preimage = folder / 'preimage' / REL
        modified = folder / 'src' / REL
        assert generation['variant'] == variant
        assert identity.sha(preimage) == generation['sourceSha256'] == selected_sources[variant][str(PRODUCTION_REL)]
        assert identity.sha(modified) == generation['generatedSourceSha256']
        assert generation['helperSha256'] == identity.sha(folder / 'src' / HELPER_REL)
        assert generation['helperSha256'] == identity.sha(HERE / 'helper-src' / HELPER_REL)
        assert generation['generatorSha256'] == identity.sha(HERE / 'build_overlay_source.py')
        assert generation['unchangedSourceRegions'] == unchanged_regions(preimage.read_text(), modified.read_text())
        if variant == 'original':
            cp, manifest = common['classpath'], common['manifest']
            production_identity = common['descriptor']['productionSourceIdentity']
        else:
            cp = common['manifest'][0]['path'] + os.pathsep + candidate['classpath']
            manifest = identity.classpath_manifest(cp)
            assert manifest[0] == common['manifest'][0] and manifest[1:] == candidate['manifest']
            production_identity = candidate['descriptor']['sourceIdentity']
        base_identity = production_identity + '+compact-page-harness-sha256-' + common['manifest'][0]['sha256']
        runtimes[variant] = {
            'classpath': cp, 'manifest': manifest, 'productionEntryIndex': 2,
            'productionSourceIdentity': production_identity, 'baseSourceIdentity': base_identity,
            'instrumentedSourceIdentity': base_identity + '+representation-diagnostic-sha256-'
                + identity.canonical_sha(sources),
            'selectedSourceSha256': generation['sourceSha256'],
            'unchangedSourceRegions': generation['unchangedSourceRegions'],
        }
    plan = {
        'format': 1, 'purpose': 'Separate representation, occupancy, hit and charge accounting only',
        'sourceHashes': sources, 'identityHelperSha256': identity.sha(PHASE / 'runtime_identity.py'),
        'descriptorInputs': {'original': common, 'candidate': candidate}, 'baseRuntimes': runtimes,
        'variants': VARIANTS, 'mode': 'dense', 'warmup': 3, 'iterations': 1, 'fixture': FIXTURE,
        'java': str(JAVA), 'jvmArguments': JVM, 'launcher': LAUNCHER,
        'javaIdentity': {'javaVersion': '25.0.5+8-LTS', 'javaVendor': 'Eclipse Adoptium', 'maxHeapBytes': 1_073_741_824},
        'queryLimitBytes': 268_435_456, 'globalLimitBytes': 1_073_741_824, 'timeoutSeconds': 300,
        'actualRouteRequired': 'Normal AUTO/native outer root, measured compiled IR, ACTIVE ready adjacency with positive lookup hits',
        'noLatencyOrAllocationComparison': True,
        'prospectiveCompactGeometry': {'compactPages': 16_384, 'densePages': 256, 'declaredPageBytes': 12_582_912},
        'failurePolicy': 'Preserve all records and failures; no replacement fork or performance-driven change.',
    }
    write_new(PLAN, plan)
    print(json.dumps({'protocol': str(PLAN), 'sha256': identity.sha(PLAN), 'javaExecuted': False}))


def read_plan():
    reject_injected_java_options()
    plan = json.loads(PLAN.read_text())
    assert plan['sourceHashes'] == source_hashes(), 'Pinned diagnostic source changed'
    assert plan['identityHelperSha256'] == identity.sha(PHASE / 'runtime_identity.py')
    assert plan['variants'] == VARIANTS and plan['fixture'] == FIXTURE and plan['jvmArguments'] == JVM
    assert (plan['warmup'], plan['iterations'], plan['mode']) == (3, 1, 'dense')
    for name, record in plan['descriptorInputs'].items():
        assert verify_descriptor(record['path']) == record, 'Frozen descriptor/runtime changed: ' + name
    for variant, base in plan['baseRuntimes'].items():
        assert identity.classpath_manifest(base['classpath']) == base['manifest'], variant
    return plan


def compile_overlays():
    plan = read_plan()
    for variant in VARIANTS:
        folder = GENERATED / variant
        raw = folder / 'compiled-output'
        selected = folder / 'classes'
        raw.mkdir(exist_ok=False)
        selected.mkdir(exist_ok=False)
        base = plan['baseRuntimes'][variant]
        argv = [str(JAVA.with_name('javac')), '-proc:none', '-implicit:none', '-encoding', 'UTF-8', '--release', '25',
                '-cp', base['classpath'], '-sourcepath', '', '-d', str(raw)]
        argv += [str(p) for p in sorted((folder / 'src').rglob('*.java'))]
        write_new(folder / 'compile-command.json', {'argv': argv, 'cwd': str(ROOT), 'startedEpochNs': time.time_ns()})
        try:
            with (folder / 'compile.log').open('xb') as log:
                completed = subprocess.run(argv, cwd=ROOT, stdout=log, stderr=subprocess.STDOUT, timeout=60)
        except subprocess.TimeoutExpired:
            write_new(folder / 'compile-result.json', {'exitCode': None, 'timedOut': True,
                                                       'finishedEpochNs': time.time_ns()})
            raise
        write_new(folder / 'compile-result.json', {'exitCode': completed.returncode, 'finishedEpochNs': time.time_ns()})
        assert completed.returncode == 0, 'Preserve failed compile; no ad hoc retry: ' + variant
        emitted = identity.tree_files(raw)
        changed = {str(REL.with_suffix('.class')), str(HELPER_REL.with_suffix('.class'))}
        unchanged = {str(REL.parent / name) for name in (
            'NativeResultMaterializerPlan.class', 'NativeResultMaterializer$FactorMemo.class',
            'NativeResultMaterializer$FactorPage.class')}
        assert set(emitted) == changed | unchanged, 'Unexpected javac class surface'
        production = Path(base['manifest'][base['productionEntryIndex']]['path'])
        selection = {}
        for name, descriptor in emitted.items():
            frozen = production / name
            selection[name] = {'compiledSha256': descriptor['sha256'],
                               'selectedFrozenSha256': identity.sha(frozen) if frozen.exists() else None,
                               'runtimeSelection': 'diagnostic overlay' if name in changed else 'unchanged frozen class'}
            if name in changed:
                target = selected / name
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(raw / name, target)
        assert identity.tree_files(selected).keys() == changed
        assert not (production / HELPER_REL.with_suffix('.class')).exists()
        cp = str(selected) + os.pathsep + base['classpath']
        manifest = identity.classpath_manifest(cp)
        assert len(manifest) == 129 and manifest[1:] == base['manifest']
        (folder / 'classpath.txt').write_text(cp + '\n')
        write_new(folder / 'classpath-manifest.json', manifest)
        write_new(folder / 'runtime.json', {
            'format': 1, 'variant': variant, 'diagnosticOnly': True, 'protocolSha256': identity.sha(PLAN),
            'sourceIdentity': base['instrumentedSourceIdentity'], 'classpath': cp, 'manifest': manifest,
            'rawJavacOutput': str(raw), 'compiledClasses': emitted, 'runtimeSelection': selection,
            'thinOverlayClasses': sorted(changed), 'frozenClassesKept': sorted(unchanged),
            'unchangedSourceRegions': base['unchangedSourceRegions'],
        })
        print(json.dumps({'compiledVariant': variant, 'runtime': str(folder / 'runtime.json'), 'benchmarkJvms': 0}), flush=True)


def read_runtime(plan, variant):
    path = GENERATED / variant / 'runtime.json'
    runtime = json.loads(path.read_text())
    assert runtime['protocolSha256'] == identity.sha(PLAN) and runtime['variant'] == variant
    assert runtime['sourceIdentity'] == plan['baseRuntimes'][variant]['instrumentedSourceIdentity']
    assert identity.classpath_manifest(runtime['classpath']) == runtime['manifest']
    assert runtime['manifest'][1:] == plan['baseRuntimes'][variant]['manifest']
    return runtime


def validate_queries(folder, plan, runtime, variant):
    records = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines()]
    assert len(records) == 5 and records[0]['type'] == 'metadata'
    metadata, samples = records[0], records[1:]
    expected_jvm = JVM + ['-D' + PROPERTY + '=' + str(folder / 'page-records'), '-D' + TRANSPORT + '=dense']
    expected = {**FIXTURE, **plan['javaIdentity'], 'arm': variant + '-dense-diagnostic',
        'source': runtime['sourceIdentity'], 'consumption': 'full', 'nativeEvaluation': True,
        'directAdjacency': True, 'valueOverlay': False, 'forceSync': False, 'directAdjacencyMode': 'PREFER',
        'globalLedgerLimitBytes': plan['globalLimitBytes'], 'perQueryLedgerLimitBytes': plan['queryLimitBytes'],
        'indexes': 'spoc,ospc,psoc,posc', 'warmup': 3, 'measurementsToRun': 1,
        'namespaceExperimentHarness': 'native-and-direct-adjacency-v1', 'jvmArguments': expected_jvm,
        'systemProperties': {'rdf4j.lmdb.hotCounters': 'true', TRANSPORT: 'dense', PROPERTY: str(folder / 'page-records')}}
    metadata_checks = {key: metadata.get(key) == value for key, value in expected.items()}
    setup = metadata['adjacencySetup']
    metadata_checks['adjacencyInitiallyReady'] = setup['state'] == 'ACTIVE' and setup['currentRevisionReady'] \
        and setup['appliedRevision'] == setup['currentDataRevision']
    checks = []
    for index, sample in enumerate(samples):
        counters, adjacency = sample['counters'], sample['adjacency']
        admissions = counters['coordinateAdmissions']
        query = {
            'index': index, 'chronology': sample['iteration'] == index - 3
                and sample['stage'] == ('warmup' if index < 3 else 'measurement'),
            'result': sample['type'] == 'sample' and sample['arm'] == variant + '-dense-diagnostic'
                and all(sample[key] for key in ('valid', 'complete', 'exactBagValid', 'rowCountValid',
                                                'checksumValid', 'partialMembershipValid'))
                and sample['rows'] == FIXTURE['expectedRows'] and sample['checksum'] == FIXTURE['expectedChecksum'],
            'ledgerReleased': sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0 and sample['ledgerReleased'],
            'oneNativeCompile': counters['semanticNativeCompiles'] == 1,
            'coordinateOwner': admissions['opened'] == 1 and admissions['initialAdmissionRefused']
                == admissions['growthAdmissionRefused'] == 0,
            'normalAutoIr': sample['autoRequested'] and sample['auto'] and bool(sample['successfulSelections'])
                and not any('forced' in item['mode'] for item in sample['successfulSelections'])
                and counters['irOpened'] == 1 and counters['irRows'] == FIXTURE['expectedRows'],
            'adjacencyActiveAndStable': adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE'
                and adjacency['appliedRevisionBefore'] == adjacency['currentRevisionBefore']
                == adjacency['appliedRevisionAfter'] == adjacency['currentRevisionAfter'] == setup['currentDataRevision'],
            'positiveAdjacencyLookupHits': adjacency['lookupHits'] > 0,
            'measuredCompiledIr': index < 3 or counters['compiledBinds'] == 1
                and counters['interpretedBinds'] == counters['aggregateCompiledBinds']
                == counters['aggregateInterpretedBinds'] == 0,
        }
        checks.append(query)
    audit = json.loads((folder / 'root-host-audit.json').read_text())
    audit_checks = {
        'schema': audit['format'] == 1 and audit['type'] == 'root-host-audit'
            and audit['readPhase'] == 'after-shared-selection-harness-main'
            and audit['harnessMain'] == 'org.eclipse.rdf4j.sail.lmdb.benchmark.SharedSelectionExperiment',
        'successfulReturn': audit['harnessReturned'] and audit['harnessFailureClass'] is None,
        'nativeRoot': audit['hostedGenericTotal'] == 0,
        'nativeCompileReconciliation': audit['semanticNativeCompilesTotal']
            == sum(s['counters']['semanticNativeCompiles'] for s in samples) == 4,
    }
    valid = all(metadata_checks.values()) and all(audit_checks.values()) \
        and all(all(value for key, value in query.items() if key != 'index') for query in checks)
    result = {'variant': variant, 'valid': valid, 'metadataChecks': metadata_checks,
              'queryChecks': checks, 'rootAuditChecks': audit_checks, 'rootAudit': audit,
              'meaning': 'Result, route and identity validation only; instrumented durations/allocations are excluded.'}
    write_new(folder / 'validation.json', result)
    assert valid, 'Preserve invalid diagnostic and inspect validation.json: ' + variant
    return metadata, samples, result


def run():
    plan = read_plan()
    destination = HERE / 'runs'
    destination.mkdir(exist_ok=False)
    for variant in VARIANTS:
        runtime = read_runtime(plan, variant)
        folder = destination / variant
        folder.mkdir()
        records = folder / 'page-records'
        records.mkdir()
        argv = [str(JAVA)] + JVM + ['-D' + PROPERTY + '=' + str(records), '-D' + TRANSPORT + '=dense',
            '-cp', runtime['classpath'], LAUNCHER, '--arm=' + variant + '-dense-diagnostic',
            '--source=' + runtime['sourceIdentity'], '--roots=64', '--left=128', '--right=128', '--tuple-width=2',
            '--warmup=3', '--iterations=1', '--consumption=full', '--store=' + str(folder / 'store'),
            '--output=' + str(folder / 'samples.jsonl')]
        write_new(folder / 'command.json', {'argv': argv, 'cwd': str(ROOT), 'protocolSha256': identity.sha(PLAN),
                  'runtimeSha256': identity.sha(GENERATED / variant / 'runtime.json'), 'startedEpochNs': time.time_ns()})
        try:
            with (folder / 'console.log').open('xb') as log:
                completed = subprocess.run(argv, cwd=ROOT, stdout=log, stderr=subprocess.STDOUT,
                                           timeout=plan['timeoutSeconds'])
        except subprocess.TimeoutExpired:
            write_new(folder / 'process-result.json', {'exitCode': None, 'timedOut': True,
                                                       'finishedEpochNs': time.time_ns()})
            raise
        write_new(folder / 'process-result.json', {'exitCode': completed.returncode, 'finishedEpochNs': time.time_ns()})
        assert completed.returncode == 0, 'Preserve failed diagnostic; no substitute fork: ' + variant
        validate_queries(folder, plan, runtime, variant)
        print(json.dumps({'completedVariant': variant, 'resultAndRouteValid': True, 'performanceInference': False}), flush=True)
    analyze()


def analyze():
    plan = read_plan()
    variants = {}
    for variant in VARIANTS:
        read_runtime(plan, variant)
        folder = HERE / 'runs' / variant
        validation = json.loads((folder / 'validation.json').read_text())
        samples = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines()][1:]
        paths = sorted((folder / 'page-records').glob('owner-*.jsonl'), key=lambda p: int(p.stem.split('-')[1]))
        owners = [analyze_owner(path) for path in paths]
        assert len(owners) == len(samples) == 4, 'Expected exactly one serial owner per query'
        for index, (owner, sample) in enumerate(zip(owners, samples), 1):
            assert owner['summary']['owner'] == index and owner['summary']['variant'] == variant
            owner['query'] = {key: sample[key] for key in ('stage', 'iteration', 'rows', 'checksum', 'exactBagValid',
                'ledgerBeforeBytes', 'ledgerPeakBytes', 'ledgerAfterBytes', 'successfulSelections', 'counters', 'adjacency')}
        variants[variant] = {'queryValidation': validation, 'owners': owners,
            'valid': validation['valid'] and all(owner['allChecksPassed']
                                               and owner['allGrantedBytesObservedAtExplicitRelease'] for owner in owners)}
    measured = {variant: value['owners'][-1] for variant, value in variants.items()}
    matching_route = measured['original']['query']['successfulSelections'] == measured['compact']['query']['successfulSelections']
    result = {'format': 1, 'validDiagnostic': matching_route and all(v['valid'] for v in variants.values()),
        'protocolSha256': identity.sha(PLAN), 'matchingMeasuredSelectionSignatures': matching_route,
        'scope': 'Two fresh diagnostic-only DENSE JVMs; each has three warmups and one measured query.',
        'instrumentationCaveat': 'Counters, extra fields, final primitive table, weak-reference observations and JSON output '
            'can alter timing, allocation and GC. None of those measurements ranks implementations here.',
        'promotionExceptionScope': 'Payload grants are observed after successful production promotion. An exceptional '
            'call makes transient internal grants/releases unobservable and fails validation; no allocation failure is injected.',
        'releaseAttributionGate': 'This diagnostic requires every grant to be observed at explicit release. Earlier '
            'ledger closure can legitimately hide that observation; it disqualifies complete attribution, not establishes a leak.',
        'adjacencyInterpretation': 'Positive query-time lookup hits include possible preparation/probes, not necessarily every row.',
        'prospectiveCompactGeometry': plan['prospectiveCompactGeometry'], 'variants': variants}
    write_new(HERE / 'analysis.json', result)
    assert result['validDiagnostic'], 'Diagnostic accounting/route validation failed; preserve every raw'
    print(json.dumps({'validDiagnostic': True, 'measured': {variant: {
        'finalTable': owner['finalTable'], 'promotions': owner['summary']['promotionSuccesses'],
        'promotionRefusals': owner['summary']['promotionRefusals'], 'factorHits': owner['summary']['factorHits'],
        'allGrantedBytesObservedAtExplicitRelease': owner['allGrantedBytesObservedAtExplicitRelease'],
        'ledgerPeakBytes': owner['query']['ledgerPeakBytes']}
        for variant, owner in measured.items()}}, indent=2))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=['prepare', 'compile', 'run', 'analyze'])
    parser.add_argument('--original-runtime', type=Path, default=PHASE / 'compiled-v1/runtime-descriptor.json')
    parser.add_argument('--candidate-runtime', type=Path, default=PHASE / 'runtimes/compact-page/runtime-descriptor.json')
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if args.action in ('compile', 'run'):
        assert args.slot_granted, 'Compilation/JVM execution requires the coordinator exclusive slot'
    if args.action == 'prepare':
        prepare(args)
    elif args.action == 'compile':
        compile_overlays()
    elif args.action == 'run':
        run()
    else:
        analyze()


if __name__ == '__main__':
    main()
